/// Native replay implementations for net bindings.
#[inline]
fn destack_net_address_local_address_replay(
    binding: &BindingCallContext,
    world: RuntimeWorld,
    out: *mut SocketAddress,
    handle: resource::SocketHandle,
) -> RuntimeResult<()> {
    let _ = &handle;

    binding.replay().run_binding_without_context(
        NET_ADDRESS_LOCAL_ADDRESS,
        binding.replay_payload_for(NET_ADDRESS_LOCAL_ADDRESS)?,
        || match world {
            RuntimeWorld::Host => unsafe {
                platform_native::destack_net_local_address(binding, out, handle)
            },
            RuntimeWorld::Simulation => unsafe {
                platform_simulation_native::destack_net_local_address(binding, out, handle)
            },
        },
        |result| {
            if let Ok(()) = result {
                let result_value = unsafe {
                    if out.is_null() {
                        return Err(RuntimeError::from(PlatformError::null_pointer("out")).boxed());
                    }
                    *out
                };
                let result_recorded_family = result_value.family;
                let result_recorded_length = result_value.length;
                let result_recorded_bytes_raw = unsafe { result_value.bytes.as_slice()? };
                let mut result_recorded_bytes = Vec::with_capacity(result_recorded_bytes_raw.len());
                for result_recorded_bytes_item_value in result_recorded_bytes_raw {
                    let result_recorded_bytes_item = *result_recorded_bytes_item_value;
                    let result_recorded_bytes_item_recorded = result_recorded_bytes_item;
                    result_recorded_bytes.push(result_recorded_bytes_item_recorded);
                }
                let result_recorded = SocketAddressReplayRecord {
                    family: result_recorded_family,
                    length: result_recorded_length,
                    bytes: result_recorded_bytes,
                };
                let payload = NetAddressLocalAddressReplay {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(ReplayError::from(error.as_ref()));
                    NetAddressLocalAddressReplay { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |payload| {
            // replay result
            match payload.result {
                Ok(value) => {
                    let value_native_family = value.family;
                    let value_native_length = value.length;
                    let mut value_native_bytes_values = Vec::with_capacity(value.bytes.len());
                    for value_native_bytes_item in value.bytes {
                        let value_native_bytes_item_native = value_native_bytes_item;
                        value_native_bytes_values.push(value_native_bytes_item_native);
                    }
                    let value_native_bytes = binding.store_array(value_native_bytes_values);
                    let value_native = SocketAddress {
                        family: value_native_family,
                        length: value_native_length,
                        bytes: value_native_bytes,
                    };
                    unsafe {
                        std::ptr::write(out, value_native);
                    }
                    Ok(())
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    )
}

