#[inline]
fn destack_net_resolve_lookup_replay(
    binding: &BindingCallContext,
    world: RuntimeWorld,
    out: *mut NativeArray<SocketAddress>,
    query: ResolveQuery,
) -> RuntimeResult<()> {
    let _ = &query;

    binding.replay().run_binding_without_context(
        NET_RESOLVE_LOOKUP,
        binding.replay_payload_for(NET_RESOLVE_LOOKUP)?,
        || match world {
            RuntimeWorld::Host => unsafe {
                platform_native::destack_net_resolve(binding, out, query)
            },
            RuntimeWorld::Simulation => unsafe {
                platform_simulation_native::destack_net_resolve(binding, out, query)
            },
        },
        |result| {
            if let Ok(()) = result {
                let result_value = unsafe {
                    if out.is_null() {
                        return Err(RuntimeError::from(PlatformError::null_pointer("out")).boxed());
                    }
                    *out
                };
                let result_recorded_raw = unsafe { result_value.as_slice()? };
                let mut result_recorded = Vec::with_capacity(result_recorded_raw.len());
                for result_recorded_item_value in result_recorded_raw {
                    let result_recorded_item = *result_recorded_item_value;
                    let result_recorded_item_recorded_family = result_recorded_item.family;
                    let result_recorded_item_recorded_length = result_recorded_item.length;
                    let result_recorded_item_recorded_bytes_raw =
                        unsafe { result_recorded_item.bytes.as_slice()? };
                    let mut result_recorded_item_recorded_bytes =
                        Vec::with_capacity(result_recorded_item_recorded_bytes_raw.len());
                    for result_recorded_item_recorded_bytes_item_value in
                        result_recorded_item_recorded_bytes_raw
                    {
                        let result_recorded_item_recorded_bytes_item =
                            *result_recorded_item_recorded_bytes_item_value;
                        let result_recorded_item_recorded_bytes_item_recorded =
                            result_recorded_item_recorded_bytes_item;
                        result_recorded_item_recorded_bytes
                            .push(result_recorded_item_recorded_bytes_item_recorded);
                    }
                    let result_recorded_item_recorded = SocketAddressReplayRecord {
                        family: result_recorded_item_recorded_family,
                        length: result_recorded_item_recorded_length,
                        bytes: result_recorded_item_recorded_bytes,
                    };
                    result_recorded.push(result_recorded_item_recorded);
                }
                let payload = NetResolveLookupReplay {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(ReplayError::from(error.as_ref()));
                    NetResolveLookupReplay { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |payload| {
            // replay result
            match payload.result {
                Ok(value) => {
                    let mut value_native_values = Vec::with_capacity(value.len());
                    for value_native_item in value {
                        let value_native_item_native_family = value_native_item.family;
                        let value_native_item_native_length = value_native_item.length;
                        let mut value_native_item_native_bytes_values =
                            Vec::with_capacity(value_native_item.bytes.len());
                        for value_native_item_native_bytes_item in value_native_item.bytes {
                            let value_native_item_native_bytes_item_native =
                                value_native_item_native_bytes_item;
                            value_native_item_native_bytes_values
                                .push(value_native_item_native_bytes_item_native);
                        }
                        let value_native_item_native_bytes =
                            binding.store_array(value_native_item_native_bytes_values);
                        let value_native_item_native = SocketAddress {
                            family: value_native_item_native_family,
                            length: value_native_item_native_length,
                            bytes: value_native_item_native_bytes,
                        };
                        value_native_values.push(value_native_item_native);
                    }
                    let value_native = binding.store_array(value_native_values);
                    unsafe {
                        std::ptr::write(out, value_native);
                    }
                    Ok(())
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    )
}

