#[inline]
fn destack_net_route_route_list_replay(
    binding: &BindingCallContext,
    world: RuntimeWorld,
    out: *mut NativeArray<RouteEntry>,
    family: SocketFamily,
) -> RuntimeResult<()> {
    let _ = &family;

    binding.replay().run_binding_without_context(
        NET_ROUTE_ROUTE_LIST,
        binding.replay_payload_for(NET_ROUTE_ROUTE_LIST)?,
        || match world {
            RuntimeWorld::Host => unsafe {
                platform_native::destack_net_route_list(binding, out, family)
            },
            RuntimeWorld::Simulation => unsafe {
                platform_simulation_native::destack_net_route_list(binding, out, family)
            },
        },
        |result| {
            if let Ok(()) = result {
                let result_value = unsafe {
                    if out.is_null() {
                        return Err(RuntimeError::from(PlatformError::null_pointer("out")).boxed());
                    }
                    *out
                };
                let result_recorded_raw = unsafe { result_value.as_slice()? };
                let mut result_recorded = Vec::with_capacity(result_recorded_raw.len());
                for result_recorded_item_value in result_recorded_raw {
                    let result_recorded_item = *result_recorded_item_value;
                    let result_recorded_item_recorded_family = result_recorded_item.family;
                    let result_recorded_item_recorded_destination_family =
                        result_recorded_item.destination.family;
                    let result_recorded_item_recorded_destination_length =
                        result_recorded_item.destination.length;
                    let result_recorded_item_recorded_destination_bytes_raw =
                        unsafe { result_recorded_item.destination.bytes.as_slice()? };
                    let mut result_recorded_item_recorded_destination_bytes = Vec::with_capacity(
                        result_recorded_item_recorded_destination_bytes_raw.len(),
                    );
                    for result_recorded_item_recorded_destination_bytes_item_value in
                        result_recorded_item_recorded_destination_bytes_raw
                    {
                        let result_recorded_item_recorded_destination_bytes_item =
                            *result_recorded_item_recorded_destination_bytes_item_value;
                        let result_recorded_item_recorded_destination_bytes_item_recorded =
                            result_recorded_item_recorded_destination_bytes_item;
                        result_recorded_item_recorded_destination_bytes
                            .push(result_recorded_item_recorded_destination_bytes_item_recorded);
                    }
                    let result_recorded_item_recorded_destination = SocketAddressReplayRecord {
                        family: result_recorded_item_recorded_destination_family,
                        length: result_recorded_item_recorded_destination_length,
                        bytes: result_recorded_item_recorded_destination_bytes,
                    };
                    let result_recorded_item_recorded_prefix_length =
                        result_recorded_item.prefix_length;
                    let result_recorded_item_recorded_gateway_family =
                        result_recorded_item.gateway.family;
                    let result_recorded_item_recorded_gateway_length =
                        result_recorded_item.gateway.length;
                    let result_recorded_item_recorded_gateway_bytes_raw =
                        unsafe { result_recorded_item.gateway.bytes.as_slice()? };
                    let mut result_recorded_item_recorded_gateway_bytes =
                        Vec::with_capacity(result_recorded_item_recorded_gateway_bytes_raw.len());
                    for result_recorded_item_recorded_gateway_bytes_item_value in
                        result_recorded_item_recorded_gateway_bytes_raw
                    {
                        let result_recorded_item_recorded_gateway_bytes_item =
                            *result_recorded_item_recorded_gateway_bytes_item_value;
                        let result_recorded_item_recorded_gateway_bytes_item_recorded =
                            result_recorded_item_recorded_gateway_bytes_item;
                        result_recorded_item_recorded_gateway_bytes
                            .push(result_recorded_item_recorded_gateway_bytes_item_recorded);
                    }
                    let result_recorded_item_recorded_gateway = SocketAddressReplayRecord {
                        family: result_recorded_item_recorded_gateway_family,
                        length: result_recorded_item_recorded_gateway_length,
                        bytes: result_recorded_item_recorded_gateway_bytes,
                    };
                    let result_recorded_item_recorded_interface_index =
                        result_recorded_item.interface_index;
                    let result_recorded_item_recorded_metric = result_recorded_item.metric;
                    let result_recorded_item_recorded_kind = result_recorded_item.kind;
                    let result_recorded_item_recorded = RouteEntryReplayRecord {
                        family: result_recorded_item_recorded_family,
                        destination: result_recorded_item_recorded_destination,
                        prefix_length: result_recorded_item_recorded_prefix_length,
                        gateway: result_recorded_item_recorded_gateway,
                        interface_index: result_recorded_item_recorded_interface_index,
                        metric: result_recorded_item_recorded_metric,
                        kind: result_recorded_item_recorded_kind,
                    };
                    result_recorded.push(result_recorded_item_recorded);
                }
                let payload = NetRouteRouteListReplay {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(ReplayError::from(error.as_ref()));
                    NetRouteRouteListReplay { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |payload| {
            // replay result
            match payload.result {
                Ok(value) => {
                    let mut value_native_values = Vec::with_capacity(value.len());
                    for value_native_item in value {
                        let value_native_item_native_family = value_native_item.family;
                        let value_native_item_native_destination_family =
                            value_native_item.destination.family;
                        let value_native_item_native_destination_length =
                            value_native_item.destination.length;
                        let mut value_native_item_native_destination_bytes_values =
                            Vec::with_capacity(value_native_item.destination.bytes.len());
                        for value_native_item_native_destination_bytes_item in
                            value_native_item.destination.bytes
                        {
                            let value_native_item_native_destination_bytes_item_native =
                                value_native_item_native_destination_bytes_item;
                            value_native_item_native_destination_bytes_values
                                .push(value_native_item_native_destination_bytes_item_native);
                        }
                        let value_native_item_native_destination_bytes =
                            binding.store_array(value_native_item_native_destination_bytes_values);
                        let value_native_item_native_destination = SocketAddress {
                            family: value_native_item_native_destination_family,
                            length: value_native_item_native_destination_length,
                            bytes: value_native_item_native_destination_bytes,
                        };
                        let value_native_item_native_prefix_length =
                            value_native_item.prefix_length;
                        let value_native_item_native_gateway_family =
                            value_native_item.gateway.family;
                        let value_native_item_native_gateway_length =
                            value_native_item.gateway.length;
                        let mut value_native_item_native_gateway_bytes_values =
                            Vec::with_capacity(value_native_item.gateway.bytes.len());
                        for value_native_item_native_gateway_bytes_item in
                            value_native_item.gateway.bytes
                        {
                            let value_native_item_native_gateway_bytes_item_native =
                                value_native_item_native_gateway_bytes_item;
                            value_native_item_native_gateway_bytes_values
                                .push(value_native_item_native_gateway_bytes_item_native);
                        }
                        let value_native_item_native_gateway_bytes =
                            binding.store_array(value_native_item_native_gateway_bytes_values);
                        let value_native_item_native_gateway = SocketAddress {
                            family: value_native_item_native_gateway_family,
                            length: value_native_item_native_gateway_length,
                            bytes: value_native_item_native_gateway_bytes,
                        };
                        let value_native_item_native_interface_index =
                            value_native_item.interface_index;
                        let value_native_item_native_metric = value_native_item.metric;
                        let value_native_item_native_kind = value_native_item.kind;
                        let value_native_item_native = RouteEntry {
                            family: value_native_item_native_family,
                            destination: value_native_item_native_destination,
                            prefix_length: value_native_item_native_prefix_length,
                            gateway: value_native_item_native_gateway,
                            interface_index: value_native_item_native_interface_index,
                            metric: value_native_item_native_metric,
                            kind: value_native_item_native_kind,
                        };
                        value_native_values.push(value_native_item_native);
                    }
                    let value_native = binding.store_array(value_native_values);
                    unsafe {
                        std::ptr::write(out, value_native);
                    }
                    Ok(())
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    )
}

