fn destack_net_uds_uds_accept_vm_replay(
    binding: &BindingCallContext,
    context: &mut vm::ExternalCallContext<'_>,
    world: RuntimeWorld,
    listener: resource::ListenerHandle,
) -> RuntimeResult<vm::Value> {
    let result = binding.replay().run_binding(
        NET_UDS_UDS_ACCEPT,
        binding.replay_payload_for(NET_UDS_UDS_ACCEPT)?,
        context,
        |context| match world {
            RuntimeWorld::Host => platform_vm::destack_net_uds_accept(binding, context, listener),
            RuntimeWorld::Simulation => {
                platform_simulation_vm::destack_net_uds_accept(binding, context, listener)
            }
        },
        |context, result| {
            let _ = &context;
            if let Ok(value) = result {
                let result_value: resource::SocketHandle = value.clone();
                let result_recorded = result_value;
                let payload = NetUdsUdsAcceptReplay {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(ReplayError::from(error.as_ref()));
                    NetUdsUdsAcceptReplay { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |context, payload| {
            let _ = &context;
            // replay result
            match payload.result {
                Ok(value) => {
                    let vm_result = value;
                    Ok(vm_result)
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    );
    let result = encode_destack_net_uds_uds_accept_result(context, result)?;
    Ok(result)
}

